'use strict';
const TODAY=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),NOW=new Date().toISOString();
const icons={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',box:'m3 7 9-4 9 4-9 4-9-4v10l9 4 9-4V7M12 11v10M7.5 5l9 4',truck:'M3 5h11v12H3zM14 9h4l3 4v4h-7M7 17a2 2 0 1 0 0 4 2 2 0 0 0 0-4M17 17a2 2 0 1 0 0 4 2 2 0 0 0 0-4',chart:'M4 3v17h17M8 15V9M13 15V5M18 15v-4',link:'m10 13 4-4M8 15l-1 1a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0M13 9l1-1a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0',book:'M4 3h13v18H4zM7 7h7M7 11h7M7 15h4M17 5h3v16h-3',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',sync:'M20 7a8 8 0 0 0-14-2L3 8m0-5v5h5M4 17a8 8 0 0 0 14 2l3-3m0 5v-5h-5',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14m5 12 6 6',plus:'M12 4v16M4 12h16',check:'m4 12 5 5L20 6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18m0 4v6h4',alert:'m12 3 10 18H2L12 3zm0 6v5m0 3v1',wallet:'M3 6h17v14H3zM3 6V3h13v3M15 11h6v5h-6z',menu:'M3 6h18M3 12h18M3 18h18',scan:'M3 8V3h5M16 3h5v5M21 16v5h-5M8 21H3v-5M7 7v10M11 7v10M15 7v10M18 7v10',print:'M6 8V3h12v5M6 16H3V9h18v7h-3M6 13h12v8H6z',users:'M8 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M1 21v-4a7 7 0 0 1 14 0v4M17 4a4 4 0 0 1 0 7M18 14a5 5 0 0 1 5 5v2'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.box}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=0)=>Number(n).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}),money=n=>'฿'+num(n,2),sum=(a,fn)=>a.reduce((v,o)=>v+fn(o),0),round=n=>Math.round(n*100)/100;
const CHANNELS=[{name:'Shopee',key:'shopee',letter:'S',color:'#eb845a'},{name:'TikTok Shop',key:'tiktok',letter:'t',color:'#34463d'},{name:'Lazada',key:'lazada',letter:'L',color:'#aa94d4'},{name:'LINE OA',key:'line',letter:'L',color:'#79b888'},{name:'Facebook',key:'facebook',letter:'f',color:'#7d9ec8'},{name:'Offline sales',key:'website',letter:'O',color:'#a2bb6d'},{name:'Review',key:'review',letter:'R',color:'#b39878'}];
const PRODUCTS=[];
const STATUS={new:'เข้าใหม่',ready:'รอหยิบสินค้า',packing:'กำลังแพ็ก',packed:'พร้อมส่ง',shipped:'จัดส่งแล้ว',delivered:'สำเร็จ',hold:'ต้องตรวจสอบ',cancelled:'ยกเลิก',returned:'คืนสินค้า'};
const titles={overview:['ภาพรวมธุรกิจ','ทุกช่องทางขาย ทุกคำสั่งซื้อ ในพื้นที่ทำงานเดียว'],orders:['คำสั่งซื้อทั้งหมด','จัดการออเดอร์จากทุกช่องทาง พร้อมตรวจรายการที่ต้องแก้ไข'],fulfillment:['เตรียมสินค้าและจัดส่ง','หยิบให้ครบ แพ็กให้ถูก แล้วส่งต่อให้ขนส่ง'],inventory:['สต๊อกสินค้า','เห็นคงเหลือ จำนวนที่กันไว้ และสินค้าที่ควรเติม'],reports:['รายงานและการเงิน','มองยอดขาย เงินรับจริง และผลตอบแทนแยกจากกัน'],connections:['เชื่อมต่อช่องทางขาย','ดูช่องทางที่ต้องใช้ สิทธิ์การเข้าถึง และขั้นตอนเชื่อมต่อ'],blueprint:['แผนพัฒนาระบบจริง','จากต้นแบบสู่ระบบที่ใช้ร่วมกันได้ทั้งทีม']};
const orders=[],payouts=[],expenses=[];let audit=[],syncCount=0;
const state={view:'overview',from:'2026-10-01',to:TODAY,channel:'',product:'',province:'',status:'all',q:'',page:1,selected:new Set(),report:'sales',packId:null,mobile:false};
function filtered(){return orders.filter(o=>(!state.from||o.date>=state.from)&&(!state.to||o.date<=state.to)&&(!state.channel||o.channel===state.channel)&&(!state.product||o.items.some(l=>l.sku===state.product))&&(!state.province||o.province===state.province))}
const netLineValue=l=>Math.max(0,l.price*l.qty-(l.discount||0));const gross=o=>sum(o.items,netLineValue)-(o.discount||0);const sales=o=>o.status==='cancelled'?0:Math.max(0,gross(o)-o.refund);const cogs=o=>['cancelled','returned'].includes(o.status)||o.channel==='Review'?0:sum(o.items,l=>l.cost*l.qty);
function stats(rows){const active=rows.filter(o=>!['cancelled','returned'].includes(o.status)&&sales(o)>0);let amount=sum(rows,sales);return {sales:amount,orders:active.length,all:rows.length,units:sum(active,o=>sum(o.items,l=>l.qty)),aov:active.length?amount/active.length:0,cancelled:rows.filter(o=>o.status==='cancelled').length,refunds:sum(rows,o=>o.refund),cogs:sum(rows,cogs)}}
function filteredPayouts(){return payouts.filter(p=>(!state.from||p.date>=state.from)&&(!state.to||p.date<=state.to)&&(!state.channel||p.channel===state.channel))}
function available(sku){const p=PRODUCTS.find(p=>p.sku===sku);return p.stock-reserved(sku)}function reserved(sku){return sum(orders.filter(o=>o.reserved),o=>sum(o.items.filter(l=>l.sku===sku),l=>l.qty))}
let channelLogo=name=>{let c=CHANNELS.find(c=>c.name===name)||CHANNELS[5];return `<span class="channel-logo ${c.key}">${c.letter}</span>`};
const badge=s=>`<span class="badge ${s}">${STATUS[s]}</span>`;const button=(label,action,ic='',cls='')=>`<button class="btn ${cls}" data-action="${action}">${ic?icon(ic):''}${label}</button>`;
function kpi(label,value,note,featured=false,ic='chart'){return `<article class="kpi ${featured?'featured':''}"><div class="label">${label}${icon(ic)}</div><div class="value">${value}</div><div class="kpi-note">${note}</div></article>`}
function toast(message){let t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),4200)}
function formatDate(d){return new Date(d+'T00:00:00+07:00').toLocaleDateString('th-TH',{timeZone:'Asia/Bangkok',day:'numeric',month:'short',year:'numeric',calendar:'gregory'})}
function filterbar(extra=false){return `<section class="filterbar" aria-label="ตัวกรอง"><label class="field">ตั้งแต่วันที่<input type="date" id="from" value="${state.from}" max="${TODAY}"></label><label class="field">ถึงวันที่<input type="date" id="to" value="${state.to}" max="${TODAY}"></label><label class="field">ช่องทาง<select id="channel"><option value="">ทุกช่องทาง</option>${CHANNELS.map(c=>`<option ${state.channel===c.name?'selected':''}>${c.name}</option>`).join('')}</select></label>${extra?`<label class="field">สินค้า<select id="product"><option value="">ทุกสินค้า</option>${PRODUCTS.map(p=>`<option value="${p.sku}" ${state.product===p.sku?'selected':''}>${esc(p.name)}</option>`).join('')}</select><span>เลือกสินค้า = ดูทั้งออเดอร์ที่มีสินค้านั้น</span></label>`:''}${button('ล้างตัวกรอง','reset','','small')}<span class="result-count">${num(filtered().length)} ออเดอร์สาธิต · THB</span></section>`}
function panel(title,sub,body,action='',cls=''){return `<section class="panel ${cls}"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}</section>`}
function chart(rows){
  const start=state.from||orders.map(o=>o.date).sort()[0]||TODAY,end=state.to||TODAY;
  const span=(Date.parse(end+'T00:00:00Z')-Date.parse(start+'T00:00:00Z'))/86400000+1;
  const monthly=span>90,period=monthly?'รายเดือน':'รายวัน',days=[];
  if(!Number.isFinite(span)||span<1)return '<div class="empty">ไม่มีข้อมูลในช่วงวันที่นี้</div>';
  if(monthly){let d=new Date(start.slice(0,7)+'-01T00:00:00Z');while(d.toISOString().slice(0,10)<=end){days.push(d.toISOString().slice(0,10));d.setUTCMonth(d.getUTCMonth()+1)}}
  else for(let t=Date.parse(start+'T00:00:00Z');t<=Date.parse(end+'T00:00:00Z');t+=86400000)days.push(new Date(t).toISOString().slice(0,10));
  const vals=days.map(d=>sum(rows.filter(o=>monthly?o.date.slice(0,7)===d.slice(0,7):o.date===d),sales));
  const max=Math.max(...vals,100),W=620,H=200,top=18,bottom=165,left=43,right=601;
  const pts=vals.map((v,i)=>[left+(i/Math.max(vals.length-1,1))*(right-left),bottom-v/max*(bottom-top)]);
  const path=pts.map((p,i)=>(i?'L':'M')+p.join(',')).join(' '),fill=path+` L${pts.at(-1)[0]},${bottom} L${pts[0][0]},${bottom} Z`;
  const label=d=>new Date(d+'T00:00:00Z').toLocaleDateString('th-TH',{timeZone:'UTC',month:'short',...(monthly?{year:'2-digit',calendar:'gregory'}:{day:'numeric'})});
  return `<svg class="trend-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="ยอดขาย${period}ตามตัวกรอง"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#f2b6ad" stop-opacity=".7"/><stop offset="1" stop-color="#fff3ef" stop-opacity=".2"/></linearGradient></defs>${[0,.25,.5,.75,1].map(t=>{let y=bottom-t*(bottom-top);return `<line x1="${left}" y1="${y}" x2="${right}" y2="${y}" stroke="#eee4e1" stroke-dasharray="3 5"/><text x="${left-10}" y="${y+3}" text-anchor="end">${num(max*t/1000,1)}k</text>`}).join('')}<path d="${fill}" fill="url(#area)"/><path d="${path}" fill="none" stroke="#bc3429" stroke-width="2.5"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#fff" stroke="#bc3429" stroke-width="2"><title>${label(days[i])} · ${money(vals[i])}</title></circle>`).join('')}${days.map((d,i)=>i%Math.ceil(days.length/7)===0||i===days.length-1?`<text x="${pts[i][0]}" y="190" text-anchor="middle">${label(d)}</text>`:'').join('')}</svg>`
}
function channelBreakdown(rows){let total=sum(rows,sales);return CHANNELS.map(c=>({c,v:sum(rows.filter(o=>o.channel===c.name),sales),n:rows.filter(o=>o.channel===c.name).length})).sort((a,b)=>b.v-a.v).map(({c,v,n})=>`<div class="channel-row">${channelLogo(c.name)}<div class="channel-name">${c.name}<div class="mini-track"><div class="mini-fill" style="width:${total?v/total*100:0}%;background:${c.color}"></div></div></div><div class="channel-value">${money(v)}<small>${n} ออเดอร์ · ${total?num(v/total*100,1):0}%</small></div></div>`).join('')}
function topProducts(rows){return PRODUCTS.map(p=>{let subset=rows.filter(o=>!['cancelled','returned'].includes(o.status)&&o.channel!=='Review');let qty=sum(subset,o=>sum(o.items.filter(l=>l.sku===p.sku),l=>l.qty));let revenue=sum(subset,o=>{let base=sum(o.items,netLineValue);return sum(o.items.filter(l=>l.sku===p.sku),netLineValue)/Math.max(base,1)*sales(o)});return {...p,qty,revenue}}).sort((a,b)=>b.revenue-a.revenue)}
function overview(){let rows=filtered(),m=stats(rows),pay=filteredPayouts();return `<div class="kpis">${kpi('ยอดขายสินค้า',money(m.sales),'หักส่วนลดผู้ขายและเงินคืน · ไม่รวมยกเลิก',true,'wallet')}${kpi('ออเดอร์ที่มีรายได้',num(m.orders)+'<span class="unit">ออเดอร์</span>',`ทั้งหมด ${m.all} · ยกเลิก ${m.cancelled}` ,false,'box')}${kpi('เงินรับจริง',money(sum(pay,p=>p.net)),'ตามวันที่เงินเข้า · แยกจากวันสั่งซื้อ',false,'wallet')}${kpi('ยอดขายเฉลี่ย / ออเดอร์',money(m.aov),`สินค้าขาย ${num(m.units)} ชิ้น`,false,'chart')}</div>
<div class="grid two">${panel('แนวโน้มยอดขาย','มูลค่าสินค้าสุทธิตามช่วงเวลาที่เลือก',`<div class="panel-body">${chart(rows)}<div class="chart-caption"><span>${formatDate(state.from||'2026-09-24')} – ${formatDate(state.to||TODAY)}</span><span>ยอดรวม ${money(m.sales)}</span></div></div>`,`<span class="badge">ตามช่วงวันที่</span>`)}${panel('ยอดขายจากแต่ละช่องทาง','สัดส่วนยอดขายหลังส่วนลดและเงินคืน',`<div class="panel-body" style="padding-top:0">${channelBreakdown(rows)}</div>`)}</div>
${panel('วันนี้ต้องจัดการอะไร','คิวงานปัจจุบันทุกวันที่สั่งซื้อ · เปลี่ยนสถานะได้จากรายการออเดอร์',`<div class="flow">${[['new','ออเดอร์เข้าใหม่','รอตรวจและกันสต๊อก','box'],['ready','รอหยิบสินค้า','เริ่มหยิบเพื่อแพ็ก','scan'],['packed','พร้อมส่ง','รอส่งมอบขนส่ง','truck'],['hold','ต้องตรวจสอบ','แก้ไขก่อนเข้าคิว','alert']].map(([s,t,n,ic])=>`<button class="flow-card ${s==='hold'?'danger':''}" data-queue="${s}"><div class="top">${t}${icon(ic)}</div><strong>${orders.filter(o=>o.status===s).length}</strong><small>${n}</small></button>`).join('')}</div>`,`<button class="text-btn" data-view="orders">ดูคำสั่งซื้อทั้งหมด</button>`)}
<div class="grid equal" style="margin-top:20px">${panel('สินค้าที่สร้างยอดขาย','จัดสรรส่วนลดและเงินคืนตามสัดส่วนมูลค่าสินค้า',`<div class="table-scroll"><table class="data-table"><thead><tr><th>สินค้า</th><th class="num">ชิ้น</th><th class="num">ยอดขาย</th></tr></thead><tbody>${topProducts(rows).map((p,i)=>`<tr><td><div class="product-line"><span class="rank">${String(i+1).padStart(2,'0')}</span><span class="product-icon">${p.sku.slice(0,3)}</span><div>${esc(p.name)}<small>${p.sku}</small></div></div></td><td class="num">${p.qty}</td><td class="num">${money(p.revenue)}</td></tr>`).join('')}</tbody></table></div>`,`<button class="text-btn" data-report="products">ดูรายงาน</button>`)}${panel('ออเดอร์ล่าสุด','เปิดรายการเพื่อดูสินค้าและประวัติ',`<div class="table-scroll"><table class="data-table"><thead><tr><th>คำสั่งซื้อ</th><th>สถานะ</th><th class="num">มูลค่า</th></tr></thead><tbody>${[...rows].sort((a,b)=>b.date.localeCompare(a.date)||b.time.localeCompare(a.time)||b.id.localeCompare(a.id)).slice(0,5).map(o=>`<tr><td><button class="order-link" data-order="${o.id}">${o.id}</button><small>${o.channel}</small></td><td>${badge(o.status)}</td><td class="num">${money(gross(o))}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">ไม่มีออเดอร์ในช่วงนี้</td></tr>'}</tbody></table></div>`,`<button class="text-btn" data-view="orders">ดูทั้งหมด</button>`)}</div>`}
function shell(){const nav=[['overview','grid','ภาพรวมธุรกิจ'],['orders','box','คำสั่งซื้อ'],['fulfillment','truck','เตรียมสินค้า / จัดส่ง'],['inventory','scan','สต๊อกสินค้า'],['reports','chart','รายงานและการเงิน'],['connections','link','เชื่อมต่อช่องทาง'],['blueprint','book','แผนพัฒนาระบบ']];document.getElementById('app').innerHTML=`<aside class="sidebar ${state.mobile?'open':''}"><div class="brand"><span class="brand-mark">${icon('box')}</span><div>ORDER HUB<small>COMMERCE WORKSPACE</small></div></div><div class="workspace"><div class="workspace-avatar">OH</div><div>ธุรกิจของคุณ<small>พื้นที่ทดลองระบบ</small></div></div><div class="nav-title">Workspace</div><nav aria-label="เมนูหลัก">${nav.map(([v,i,n])=>`<button class="nav ${state.view===v?'active':''}" data-view="${v}">${icon(i)}${n}${v==='orders'?`<span class="count">${orders.filter(o=>['new','ready','packing','packed'].includes(o.status)).length}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><strong>ครบทุกขั้นตอนในที่เดียว</strong><p>รับออเดอร์ · หยิบแพ็ก · จัดส่ง<br>ติดตามยอดขายและรายรับ</p><p style="margin-top:12px">Prototype v0.2 · ข้อมูลสาธิต</p></div></aside><main class="main"><header class="topbar"><button class="mobile-toggle" data-action="menu" aria-label="เปิดหรือปิดเมนู" aria-expanded="${state.mobile}">${icon('menu')}</button><div class="crumb"><span>พื้นที่ทำงาน /</span><strong>${titles[state.view][0]}</strong></div><div class="top-right"><span class="top-date">${formatDate(TODAY)}</span><span class="demo-badge">DEMO · ยังไม่เชื่อมร้านจริง</span><span class="avatar">OH</span></div></header><div class="content"><section class="heading"><div><div class="eyebrow">${state.view==='overview'?'BUSINESS AT A GLANCE':'ORDER HUB / '+state.view.toUpperCase()}</div><h1>${titles[state.view][0]}</h1><p>${titles[state.view][1]}</p></div><div class="actions">${state.view==='connections'?button('ทดลองรับออเดอร์','sync','sync','primary'):state.view==='orders'?button('เพิ่มออเดอร์สาธิต','new-order','plus','primary'):state.view==='fulfillment'?button('พิมพ์ใบหยิบสินค้า','picklist','print'):state.view==='blueprint'?'':button('ส่งออก CSV','export','download')}${state.view==='overview'?button('จัดการออเดอร์','go-orders','box','primary'):''}</div></section>${['overview','orders','reports'].includes(state.view)?filterbar(state.view==='reports'&&state.report!=='finance'):''}<div id="view-content">${renderView()}</div><footer class="page-foot"><span>Order Hub · ตัวอย่างข้อมูลสมมติทั้งหมด ไม่ใช่ยอดธุรกิจจริง</span><span>บันทึกข้อมูลในเครื่องนี้ · ข้อมูลธุรกิจยังเป็นตัวอย่าง</span></footer></div></main>`;bind();}
function renderView(){if(state.view==='overview')return overview();if(typeof views!=='undefined'&&views[state.view])return views[state.view]();return '<div class="panel"><div class="empty">กำลังเตรียมพื้นที่ทำงานส่วนนี้</div></div>'}
function changeView(v){if(!titles[v])return;state.view=v;state.mobile=false;state.selected.clear();state.page=1;if(v!=='reports'){state.product='';state.province=''}shell();window.scrollTo({top:0,behavior:'instant'})}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>changeView(b.dataset.view));document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{state.report=b.dataset.report;changeView('reports')});document.querySelectorAll('[data-queue]').forEach(b=>b.onclick=()=>{state.status=b.dataset.queue;state.from='';state.to='';state.channel='';state.q='';changeView('orders')});for(let id of ['from','to','channel','product','province']){let el=document.getElementById(id);if(el)el.onchange=()=>{let val=el.value;if(id==='from'&&state.to&&val>state.to||id==='to'&&state.from&&val<state.from){el.value=state[id];toast('วันที่เริ่มต้นต้องไม่เกินวันสิ้นสุด');return}state[id]=val;state.page=1;state.selected.clear();shell()}}document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>showOrder(b.dataset.order));if(typeof bindViews==='function')bindViews()}
function action(a){if(a==='menu'){state.mobile=!state.mobile;document.querySelector('.sidebar').classList.toggle('open',state.mobile);return}if(a==='reset'){Object.assign(state,{from:'2026-10-01',to:TODAY,channel:'',product:'',province:'',q:'',status:'all',page:1});state.selected.clear();shell();return}if(a==='go-orders'){changeView('orders');return}if(typeof extraAction==='function')extraAction(a)}
let views={};
